BEFORE UPDATE ON public.support_staff
FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

CREATE TRIGGER update_support_tasks_updated_at
BEFORE UPDATE ON public.support_tasks
FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

