RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT NOT EXISTS (
    SELECT 1 FROM public.applications
    WHERE email = _email
      AND status IN ('pending'::application_status, 'under_review'::application_status)
  )
$$;

