-- ---- legal_agreements -----------------------------------------------------
CREATE OR REPLACE FUNCTION public.enforce_legal_agreement_column_scope()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  uid    uuid   := auth.uid();
  denied text[] := '{}';
  vals   jsonb  := '{}'::jsonb;
BEGIN
  IF public.is_admin() THEN RETURN NEW; END IF;

  IF uid = OLD.driver_id AND uid <> COALESCE(OLD.owner_id, '00000000-0000-0000-0000-000000000000'::uuid) THEN
    IF NEW.owner_signature IS DISTINCT FROM OLD.owner_signature THEN
      denied := denied || ARRAY['owner_signature']; vals := vals || jsonb_build_object('owner_signature', NEW.owner_signature);
      NEW.owner_signature := OLD.owner_signature; END IF;
    IF NEW.owner_signed_at IS DISTINCT FROM OLD.owner_signed_at THEN denied := denied || ARRAY['owner_signed_at']; NEW.owner_signed_at := OLD.owner_signed_at; END IF;
    IF NEW.admin_witness_signature IS DISTINCT FROM OLD.admin_witness_signature THEN denied := denied || ARRAY['admin_witness_signature']; NEW.admin_witness_signature := OLD.admin_witness_signature; END IF;
