  IF NEW.actual_downtime_hours IS DISTINCT FROM OLD.actual_downtime_hours THEN denied := denied || ARRAY['actual_downtime_hours']; NEW.actual_downtime_hours := OLD.actual_downtime_hours; END IF;
  IF NEW.estimated_downtime_hours IS DISTINCT FROM OLD.estimated_downtime_hours THEN denied := denied || ARRAY['estimated_downtime_hours']; NEW.estimated_downtime_hours := OLD.estimated_downtime_hours; END IF;
  IF NEW.reported_at IS DISTINCT FROM OLD.reported_at THEN denied := denied || ARRAY['reported_at']; NEW.reported_at := OLD.reported_at; END IF;
  IF NEW.driver_id IS DISTINCT FROM OLD.driver_id THEN denied := denied || ARRAY['driver_id']; NEW.driver_id := OLD.driver_id; END IF;
  IF NEW.owner_id IS DISTINCT FROM OLD.owner_id THEN denied := denied || ARRAY['owner_id']; NEW.owner_id := OLD.owner_id; END IF;
  IF NEW.vehicle_id IS DISTINCT FROM OLD.vehicle_id THEN denied := denied || ARRAY['vehicle_id']; NEW.vehicle_id := OLD.vehicle_id; END IF;
  IF NEW.incident_type IS DISTINCT FROM OLD.incident_type THEN denied := denied || ARRAY['incident_type']; NEW.incident_type := OLD.incident_type; END IF;

  IF array_length(denied, 1) > 0 THEN
    PERFORM public.log_permission_denied('vehicle_incidents', OLD.id::text,
      'Non-admin/non-support attempted to change severity, IoT data, or resolution fields on incident',
      denied, vals);
    RAISE NOTICE 'Blocked update to protected vehicle_incidents fields: %', denied;
  END IF;
  RETURN NEW;
END;
$$;

-- ---- weekly_inspection_reports -------------------------------------------
CREATE OR REPLACE FUNCTION public.enforce_weekly_report_column_scope()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $$
DECLARE
  uid    uuid   := auth.uid();
  denied text[] := '{}';
  vals   jsonb  := '{}'::jsonb;
BEGIN
  IF public.is_admin() THEN RETURN NEW; END IF;

  IF uid = OLD.driver_id AND uid <> COALESCE(OLD.owner_id, '00000000-0000-0000-0000-000000000000'::uuid) THEN
    IF NEW.owner_reviewed_at IS DISTINCT FROM OLD.owner_reviewed_at THEN denied := denied || ARRAY['owner_reviewed_at']; NEW.owner_reviewed_at := OLD.owner_reviewed_at; END IF;
    IF NEW.owner_notes IS DISTINCT FROM OLD.owner_notes THEN denied := denied || ARRAY['owner_notes']; NEW.owner_notes := OLD.owner_notes; END IF;
    IF NEW.owner_action IS DISTINCT FROM OLD.owner_action THEN denied := denied || ARRAY['owner_action']; vals := vals || jsonb_build_object('owner_action', NEW.owner_action); NEW.owner_action := OLD.owner_action; END IF;
    IF NEW.admin_reviewed_at IS DISTINCT FROM OLD.admin_reviewed_at THEN denied := denied || ARRAY['admin_reviewed_at']; NEW.admin_reviewed_at := OLD.admin_reviewed_at; END IF;
    IF NEW.admin_decision IS DISTINCT FROM OLD.admin_decision THEN denied := denied || ARRAY['admin_decision']; NEW.admin_decision := OLD.admin_decision; END IF;
    IF NEW.admin_notes IS DISTINCT FROM OLD.admin_notes THEN denied := denied || ARRAY['admin_notes']; NEW.admin_notes := OLD.admin_notes; END IF;
    IF NEW.admin_id IS DISTINCT FROM OLD.admin_id THEN denied := denied || ARRAY['admin_id']; NEW.admin_id := OLD.admin_id; END IF;
    IF NEW.driver_id IS DISTINCT FROM OLD.driver_id THEN denied := denied || ARRAY['driver_id']; NEW.driver_id := OLD.driver_id; END IF;
    IF NEW.owner_id IS DISTINCT FROM OLD.owner_id THEN denied := denied || ARRAY['owner_id']; NEW.owner_id := OLD.owner_id; END IF;
    IF NEW.vehicle_id IS DISTINCT FROM OLD.vehicle_id THEN denied := denied || ARRAY['vehicle_id']; NEW.vehicle_id := OLD.vehicle_id; END IF;
    IF NEW.week_start_date IS DISTINCT FROM OLD.week_start_date THEN denied := denied || ARRAY['week_start_date']; NEW.week_start_date := OLD.week_start_date; END IF;

  ELSIF uid = OLD.owner_id THEN
    IF NEW.photo_front_view IS DISTINCT FROM OLD.photo_front_view THEN denied := denied || ARRAY['photo_front_view']; NEW.photo_front_view := OLD.photo_front_view; END IF;
    IF NEW.photo_back_view IS DISTINCT FROM OLD.photo_back_view THEN denied := denied || ARRAY['photo_back_view']; NEW.photo_back_view := OLD.photo_back_view; END IF;
    IF NEW.photo_driver_side IS DISTINCT FROM OLD.photo_driver_side THEN denied := denied || ARRAY['photo_driver_side']; NEW.photo_driver_side := OLD.photo_driver_side; END IF;
    IF NEW.photo_passenger_side IS DISTINCT FROM OLD.photo_passenger_side THEN denied := denied || ARRAY['photo_passenger_side']; NEW.photo_passenger_side := OLD.photo_passenger_side; END IF;
    IF NEW.photo_front_right_tyre IS DISTINCT FROM OLD.photo_front_right_tyre THEN denied := denied || ARRAY['photo_front_right_tyre']; NEW.photo_front_right_tyre := OLD.photo_front_right_tyre; END IF;
    IF NEW.photo_front_left_tyre IS DISTINCT FROM OLD.photo_front_left_tyre THEN denied := denied || ARRAY['photo_front_left_tyre']; NEW.photo_front_left_tyre := OLD.photo_front_left_tyre; END IF;
    IF NEW.photo_back_left_tyre IS DISTINCT FROM OLD.photo_back_left_tyre THEN denied := denied || ARRAY['photo_back_left_tyre']; NEW.photo_back_left_tyre := OLD.photo_back_left_tyre; END IF;
    IF NEW.photo_back_right_tyre IS DISTINCT FROM OLD.photo_back_right_tyre THEN denied := denied || ARRAY['photo_back_right_tyre']; NEW.photo_back_right_tyre := OLD.photo_back_right_tyre; END IF;
    IF NEW.photo_dashboard IS DISTINCT FROM OLD.photo_dashboard THEN denied := denied || ARRAY['photo_dashboard']; NEW.photo_dashboard := OLD.photo_dashboard; END IF;
    IF NEW.photo_interior IS DISTINCT FROM OLD.photo_interior THEN denied := denied || ARRAY['photo_interior']; NEW.photo_interior := OLD.photo_interior; END IF;
    IF NEW.photo_rideshare_profile IS DISTINCT FROM OLD.photo_rideshare_profile THEN denied := denied || ARRAY['photo_rideshare_profile']; NEW.photo_rideshare_profile := OLD.photo_rideshare_profile; END IF;
    IF NEW.photo_timestamps IS DISTINCT FROM OLD.photo_timestamps THEN denied := denied || ARRAY['photo_timestamps']; NEW.photo_timestamps := OLD.photo_timestamps; END IF;
    IF NEW.submitted_at IS DISTINCT FROM OLD.submitted_at THEN denied := denied || ARRAY['submitted_at']; NEW.submitted_at := OLD.submitted_at; END IF;
    IF NEW.driver_responded_at IS DISTINCT FROM OLD.driver_responded_at THEN denied := denied || ARRAY['driver_responded_at']; NEW.driver_responded_at := OLD.driver_responded_at; END IF;
    IF NEW.driver_accepted_withdrawal IS DISTINCT FROM OLD.driver_accepted_withdrawal THEN denied := denied || ARRAY['driver_accepted_withdrawal']; NEW.driver_accepted_withdrawal := OLD.driver_accepted_withdrawal; END IF;
    IF NEW.admin_reviewed_at IS DISTINCT FROM OLD.admin_reviewed_at THEN denied := denied || ARRAY['admin_reviewed_at']; NEW.admin_reviewed_at := OLD.admin_reviewed_at; END IF;
    IF NEW.admin_decision IS DISTINCT FROM OLD.admin_decision THEN denied := denied || ARRAY['admin_decision']; NEW.admin_decision := OLD.admin_decision; END IF;
    IF NEW.admin_notes IS DISTINCT FROM OLD.admin_notes THEN denied := denied || ARRAY['admin_notes']; NEW.admin_notes := OLD.admin_notes; END IF;
    IF NEW.admin_id IS DISTINCT FROM OLD.admin_id THEN denied := denied || ARRAY['admin_id']; NEW.admin_id := OLD.admin_id; END IF;
    IF NEW.driver_id IS DISTINCT FROM OLD.driver_id THEN denied := denied || ARRAY['driver_id']; NEW.driver_id := OLD.driver_id; END IF;
    IF NEW.owner_id IS DISTINCT FROM OLD.owner_id THEN denied := denied || ARRAY['owner_id']; NEW.owner_id := OLD.owner_id; END IF;
    IF NEW.vehicle_id IS DISTINCT FROM OLD.vehicle_id THEN denied := denied || ARRAY['vehicle_id']; NEW.vehicle_id := OLD.vehicle_id; END IF;
    IF NEW.week_start_date IS DISTINCT FROM OLD.week_start_date THEN denied := denied || ARRAY['week_start_date']; NEW.week_start_date := OLD.week_start_date; END IF;
  END IF;

  IF array_length(denied, 1) > 0 THEN
    PERFORM public.log_permission_denied('weekly_inspection_reports', OLD.id::text,
      'Non-admin attempted to modify fields outside their role scope on inspection report',
      denied, vals);
    RAISE NOTICE 'Blocked update to protected weekly_inspection_reports fields: %', denied;
  END IF;
  RETURN NEW;
END;
$$;


