  AND final_daily_rate IS NULL
  AND COALESCE(is_locked, false) = false
  AND EXISTS (
    SELECT 1 FROM public.vehicles v
    WHERE v.id = price_negotiations.vehicle_id
      AND v.owner_id = auth.uid()
  )
);

