CREATE OR REPLACE FUNCTION public.get_verification_trace(p_correlation_id text)
RETURNS SETOF public.verification_event_log
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT *
  FROM public.verification_event_log
