         a.rejection_reason,
         r.reason,
         r.documents,
         r.status,
         r.resolution_notes,
         r.reviewed_at,
         r.created_at
    FROM public.application_recovery_requests r
    JOIN public.applications a ON a.id = r.application_id
   WHERE r.requested_by = auth.uid()
   ORDER BY r.created_at DESC;
$$;

