  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  phone TEXT NOT NULL,
  channel TEXT NOT NULL DEFAULT 'all',
  user_id UUID,
  opted_out_at TIMESTAMPTZ,
