USING (
  public.has_admin_privilege(auth.uid(), 'can_manage_users')
  OR public.support_staff_region_match(region)
)
WITH CHECK (
  public.has_admin_privilege(auth.uid(), 'can_manage_users')
  OR public.support_staff_region_match(region)
);

