ON public.vehicle_geofences FOR ALL TO authenticated
USING (public.is_admin() OR public.has_role(auth.uid(), 'iot_support'::app_role))
WITH CHECK (public.is_admin() OR public.has_role(auth.uid(), 'iot_support'::app_role));

