RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = public
AS $$
BEGIN
  NEW.updated_at := now();
  IF NEW.status IN ('resolved','closed') AND (OLD.status IS DISTINCT FROM NEW.status) THEN
    NEW.resolved_at := now();
  END IF;
  RETURN NEW;
END;
$$;

